        /// <summary>del d[key] / del xs[i]</summary>
        public static void delitem<K, V>(IDictionary<K, V> d, K key) { if (!d.Remove(key)) throw new KeyNotFoundException(repr(key)); }
        public static void delitem<T>(List<T> xs, long i)
        {
