        // ───────────── positions: a negative index counts from the end (xs[-k], xs[i - 1] at i == 0) ─────────────
        // fast path: one unsigned compare (0 <= i < count); the rest (negative, or out of range: the indexer raises IndexError)
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int __pos(long i, int count) => (ulong)i < (ulong)count ? (int)i : __pos_slow(i, count);
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int __pos(int i, int count) => (uint)i < (uint)count ? i : __pos_slow(i, count);
        [MethodImpl(MethodImplOptions.NoInlining)]
        static int __pos_slow(long i, int count) => i < 0 ? (int)Math.Max(i + count, int.MinValue) : (int)Math.Min(i, int.MaxValue);
        public static int __pos(BigInteger i, int count) => __pos(checked((long)i), count);
        public static int __pos(object i, int count) => i is BigInteger b ? __pos(b, count) : __pos(Convert.ToInt64(i, Inv), count);

        static bool IsIndex(object? k) => k is long || k is int || k is BigInteger || k is bool || k is short || k is byte;

        /// <summary>o[key] of a late-bound value: list/str/tuple positions (Python ints, negative from the end) or a mapping's key.</summary>
        public static dynamic? __getitem(object? o, object? key)
        {
            switch (o)
            {
                // a dict first: .NET's OrderedDictionary is an IList too, but d[3] is a key, not a position
                case IDictionary d:
                {
                    var k = KeyFor(d, key);
                    if (!d.Contains(k!)) throw new KeyNotFoundException(repr(key));
                    return d[k!];
                }
                case string s when IsIndex(key): return str_at(s, __pos(key is bool kb ? (kb ? 1L : 0L) : key!, s.Length));
                case IList list when IsIndex(key): return list[__pos(key is bool lb ? (lb ? 1L : 0L) : key!, list.Count)];
                case ITuple t when IsIndex(key): return t[__pos(key is bool tb ? (tb ? 1L : 0L) : key!, t.Length)];
                case null: throw new NullReferenceException("'NoneType' object is not subscriptable");
            }
            if (IsIndex(key) && o is not IDictionary)
            {
                dynamic dyn = o;
                try { int count = (int)dyn.Count; return dyn[__pos(key!, count)]; }
                catch (Microsoft.CSharp.RuntimeBinder.RuntimeBinderException) { }
            }
            // obj[x, y]: a Typhon class takes the tuple as one key; a .NET indexer with several parameters takes its items
            if (key is ITuple tk && key is not IPyTuple)
            {
                try { return ((dynamic)o)[(dynamic)key]; }
                catch (Microsoft.CSharp.RuntimeBinder.RuntimeBinderException) { return IndexItems((dynamic)o, tk); }
            }
            return ((dynamic)o)[(dynamic?)key];
        }

        static dynamic IndexItems(dynamic o, ITuple k) => k.Length switch
        {
            2 => o[(dynamic?)k[0], (dynamic?)k[1]],
            3 => o[(dynamic?)k[0], (dynamic?)k[1], (dynamic?)k[2]],
            4 => o[(dynamic?)k[0], (dynamic?)k[1], (dynamic?)k[2], (dynamic?)k[3]],
            _ => o[(dynamic)k],
        };

        static void SetIndexItems(dynamic o, ITuple k, dynamic? value)
        {
            switch (k.Length)
            {
                case 2: o[(dynamic?)k[0], (dynamic?)k[1]] = value; break;
                case 3: o[(dynamic?)k[0], (dynamic?)k[1], (dynamic?)k[2]] = value; break;
                case 4: o[(dynamic?)k[0], (dynamic?)k[1], (dynamic?)k[2], (dynamic?)k[3]] = value; break;
                default: o[(dynamic)k] = value; break;
            }
        }

        /// <summary>o[key] = value on a late-bound value.</summary>
        public static void __setitem(object? o, object? key, object? value)
        {
            switch (o)
            {
                case IDictionary d: d[KeyFor(d, key)!] = value; return;
                case IList list when IsIndex(key): list[__pos(key is bool lb ? (lb ? 1L : 0L) : key!, list.Count)] = value; return;
                case null: throw new NullReferenceException("'NoneType' object does not support item assignment");
            }
            if (key is ITuple tk && key is not IPyTuple)
            {
                try { ((dynamic)o)[(dynamic)key] = (dynamic?)value; }
                catch (Microsoft.CSharp.RuntimeBinder.RuntimeBinderException) { SetIndexItems((dynamic)o, tk, value); }
                return;
            }
            ((dynamic)o)[(dynamic?)key] = (dynamic?)value;
        }
        /// <summary>xs[i] of a list that is not a plain variable (evaluated once); assignable: __at(f(), i) = v.</summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static ref T __at<T>(List<T> xs, long i)
        {
            var items = System.Runtime.InteropServices.CollectionsMarshal.AsSpan(xs);
            // 0 <= i < Count, checked once: no second bounds check
            if ((ulong)i < (ulong)items.Length) return ref Unsafe.Add(ref System.Runtime.InteropServices.MemoryMarshal.GetReference(items), (nint)i);
            return ref xs.__at_slow(i);
        }
        [MethodImpl(MethodImplOptions.NoInlining)]
        static ref T __at_slow<T>(this List<T> xs, long i)
        {
            if (i < 0 && i + xs.Count >= 0) return ref System.Runtime.InteropServices.CollectionsMarshal.AsSpan(xs)[(int)(i + xs.Count)];
            throw new ArgumentOutOfRangeException(nameof(i), "list index out of range");
        }
        public static ref T __at<T>(List<T> xs, BigInteger i) => ref System.Runtime.InteropServices.CollectionsMarshal.AsSpan(xs)[__pos(i, xs.Count)];
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static ref T __at<T>(T[] xs, long i)
        {
            if ((ulong)i < (ulong)xs.Length) return ref Unsafe.Add(ref System.Runtime.InteropServices.MemoryMarshal.GetArrayDataReference(xs), (nint)i);
            return ref xs[__pos(i, xs.Length)];
        }
