        /// <summary>Python orders strings by code point, .NET's default comparer is culture-aware: use ordinal.</summary>
        internal static IComparer<T> PyComparer<T>() => typeof(T) == typeof(string) ? (IComparer<T>)(object)StringComparer.Ordinal
            : typeof(T) == typeof(object) ? (IComparer<T>)(object)PyObjectComparer.Instance
            // tuples order item by item with Python's rules (strs by code point, not by culture)
            : typeof(ITuple).IsAssignableFrom(typeof(T)) && typeof(T).IsValueType ? Comparer<T>.Create((a, b) => compare(a, b)) : Comparer<T>.Default;

        /// <summary>Late-bound values (List&lt;dynamic&gt;) order by Python's rules: strs by code point, numbers by value, sequences lexicographically.</summary>
        sealed class PyObjectComparer : IComparer<object?>
        {
            public static readonly PyObjectComparer Instance = new PyObjectComparer();
            public int Compare(object? a, object? b) => compare(a, b);
        }
        /// <summary>Equal values of these types are indistinguishable, so an unstable (faster) sort gives Python's result.</summary>
        static bool StabilityIrrelevant<T>() => typeof(T).IsPrimitive || typeof(T) == typeof(string) || typeof(T) == typeof(decimal);

        public static List<T> sorted<T>(IEnumerable<T> xs, bool reverse = false)
        {
            var cmp = PyComparer<T>();
            if (StabilityIrrelevant<T>())
            {
                var l = new List<T>(xs);
                l.Sort(cmp);
                if (reverse) l.Reverse();
                return l;
            }
            return (reverse ? xs.OrderByDescending(x => x, cmp) : xs.OrderBy(x => x, cmp)).ToList(); // stable, like Timsort
        }
        public static List<T> sorted<T, K>(IEnumerable<T> xs, Func<T, K> key, bool reverse = false)
            => (reverse ? xs.OrderByDescending(key, PyComparer<K>()) : xs.OrderBy(key, PyComparer<K>())).ToList();
