        static void CheckUnpack(int count, int expected)
        {
            if (count != expected) throw new ArgumentException(count > expected ? $"too many values to unpack (expected {expected})" : $"not enough values to unpack (expected {expected}, got {count})");
        }
        public static void Deconstruct<T>(this IList<T> l, out T a, out T b) { CheckUnpack(l.Count, 2); a = l[0]; b = l[1]; }
        public static void Deconstruct<T>(this IList<T> l, out T a, out T b, out T c) { CheckUnpack(l.Count, 3); a = l[0]; b = l[1]; c = l[2]; }
        public static void Deconstruct<T>(this IList<T> l, out T a, out T b, out T c, out T d) { CheckUnpack(l.Count, 4); a = l[0]; b = l[1]; c = l[2]; d = l[3]; }

