                if (parts1 < 0 || parts.Length <= parts1) return parts.ToList();
                return s.TrimStart().Split((char[]?)null, parts1, StringSplitOptions.RemoveEmptyEntries).ToList();
            }
            return (parts1 < 0 ? s.Split(sep) : s.Split(sep, parts1)).ToList();
        }
